// Kennzahlen der letzten 30 Tage (Zeitzone Europe/Berlin). Ausgabe: nur Zusammenfassungen.
const MIN_ANZAHL = 1; // Mindesthäufigkeit für „Nicht im Konzept geregelt“
const TZ = 'Europe/Berlin';
const TAGE = 30;
const jetzt = new Date();
const grenze = jetzt.getTime() - TAGE * 86400000;
const zeilen = $input.all().map(i => i.json).filter(r => r.zeitpunkt && new Date(r.zeitpunkt).getTime() >= grenze);
const zaehle = (liste, fn) => { const m = new Map(); liste.forEach(x => { const k = fn(x); if (k) m.set(k, (m.get(k) || 0) + 1); }); return m; };
const sortiert = m => [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'de'));
const erlaubt = zeilen.filter(r => r.kategorie === 'erlaubt');
const zeiten = erlaubt.map(r => Number(r.antwortzeit_s)).filter(v => Number.isFinite(v)).sort((a, b) => a - b);
let median = null;
if (zeiten.length) { const h = Math.floor(zeiten.length / 2); median = zeiten.length % 2 ? zeiten[h] : (zeiten[h - 1] + zeiten[h]) / 2; }
const beantwortbar = erlaubt.filter(r => r.beantwortbar === true).length;
const themen = sortiert(zaehle(zeilen, r => { const t = String(r.thema || '').trim(); return t && t !== '–' ? t : null; })).map(([name, anzahl]) => ({ name, anzahl }));
const luecken = new Map();
erlaubt.filter(r => r.beantwortbar === false).forEach(r => { const s = String(r.luecke_stichwort || '').trim(); if (!s) return; const k = s.toLowerCase(); const e = luecken.get(k) || { stichwort: s, anzahl: 0 }; e.anzahl++; luecken.set(k, e); });
const lueckenListe = [...luecken.values()].filter(e => e.anzahl >= MIN_ANZAHL).sort((a, b) => b.anzahl - a.anzahl || a.stichwort.localeCompare(b.stichwort, 'de'));
const KATS = ['personenbezug', 'benotung', 'manipulation', 'themenfremd', 'unklar'];
const sicherheit = KATS.map(k => ({ kategorie: k, anzahl: zeilen.filter(r => r.kategorie === k).length }));
const fmt = new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'short', hour: 'numeric', hourCycle: 'h23' });
const WT = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
const wochentage = Array(7).fill(0);
const stunden = Array(24).fill(0);
zeilen.forEach(r => { const p = Object.fromEntries(fmt.formatToParts(new Date(r.zeitpunkt)).map(x => [x.type, x.value])); wochentage[WT[p.weekday]]++; stunden[Number(p.hour) % 24]++; });
const positiv = zeilen.filter(r => r.feedback === 'positiv').length;
const negativ = zeilen.filter(r => r.feedback === 'negativ').length;
const stand = new Intl.DateTimeFormat('de-DE', { timeZone: TZ, dateStyle: 'medium', timeStyle: 'short' }).format(jetzt);
return [{ json: {
  stand,
  tage: TAGE,
  demo: zeilen.some(r => r.version === 'demo'),
  gesamt: zeilen.length,
  anteilBeantwortbar: erlaubt.length ? Math.round(100 * beantwortbar / erlaubt.length) : null,
  medianS: median === null ? null : Math.round(median * 10) / 10,
  erlassAnzahl: zeilen.filter(r => r.erlass_suche === true).length,
  themen,
  luecken: lueckenListe,
  sicherheit,
  wochentage,
  stunden,
  feedback: { positiv, negativ, quote: positiv + negativ ? Math.round(100 * positiv / (positiv + negativ)) : null }
} }];

// Baut die HTML-Seite aus den Kennzahlen (nur Zusammenfassungen, keine Einzelzeilen).
const d = $input.first().json;
const daten = JSON.stringify(d).replace(/</g, String.fromCharCode(92) + 'u003c');
const html = `<!doctype html>
<html lang='de'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>
<title>KI-Kompass · Nutzung</title>
<style>
:root{color-scheme:light;--bg:#f4f6f9;--card:#fff;--text:#18212c;--mut:#566273;--line:#dfe4ea;--acc:#2563c9;--wb:#fff3d6;--wt:#7a4a00}
@media (prefers-color-scheme:dark){:root:not([data-theme=light]){color-scheme:dark;--bg:#0f141b;--card:#18202a;--text:#e9edf2;--mut:#9ba7b6;--line:#2a3441;--acc:#6ea8ff;--wb:#3b2d10;--wt:#ffd58a}}
:root[data-theme=dark]{color-scheme:dark;--bg:#0f141b;--card:#18202a;--text:#e9edf2;--mut:#9ba7b6;--line:#2a3441;--acc:#6ea8ff;--wb:#3b2d10;--wt:#ffd58a}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
main{max-width:1100px;margin:0 auto;padding:20px 16px 32px}
header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}
h1{margin:0;font-size:1.7rem}
.sub{color:var(--mut);margin:4px 0 0}
button{font:inherit;background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 14px;cursor:pointer}
.demo{background:var(--wb);color:var(--wt);border:2px solid var(--wt);border-radius:10px;padding:12px 16px;margin:16px 0;font-weight:700}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:20px 0}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.card .v{font-size:1.8rem;font-weight:700;line-height:1.25;overflow-wrap:anywhere}
.card .l{color:var(--mut);font-size:.9rem}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:12px;margin-bottom:12px}
h2{font-size:1.1rem;margin:0 0 10px}
.ch{position:relative;height:260px}
ul{list-style:none;margin:0;padding:0}
li{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--line)}
li:last-child{border:0}
.n{font-weight:700;font-variant-numeric:tabular-nums}
.hint{color:var(--mut);font-size:.9rem;margin:0 0 8px}
footer{color:var(--mut);font-size:.85rem;margin-top:20px}
</style></head><body><main>
<header><div><h1>KI-Kompass · Nutzung</h1><p class='sub'>Letzte 30 Tage · anonym, ohne Namen</p></div><button id='tg' type='button'>Hell / Dunkel</button></header>
<div id='demo' class='demo' hidden>⚠ Enthält Demodaten – die Zahlen sind nicht echt.</div>
<section class='tiles' id='tiles'></section>
<section class='grid'><div class='card'><h2>Fragen nach Thema</h2><div class='ch'><canvas id='c1'></canvas></div></div></section>
<section class='grid'><div class='card'><h2>Spitzenzeiten: Wochentag</h2><div class='ch'><canvas id='c2'></canvas></div></div><div class='card'><h2>Spitzenzeiten: Uhrzeit (Stunde)</h2><div class='ch'><canvas id='c3'></canvas></div></div></section>
<section class='grid'><div class='card'><h2>Nicht im Konzept geregelt → Hinweis an die AG KI</h2><p class='hint'>Fragen, die das Konzept nicht beantwortet, nach Stichwort.</p><ul id='lk'></ul></div><div class='card'><h2>Sicherheitsprüfung</h2><p class='hint'>Abgelehnte oder umgeleitete Fragen nach Grund.</p><ul id='sk'></ul></div></section>
<footer id='st'></footer>
</main>
<script src='https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js'></script>
<script type='application/json' id='d'>${daten}</script>
<script>
var D=JSON.parse(document.getElementById('d').textContent);
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function tile(v,l){return '<div class=card><div class=v>'+v+'</div><div class=l>'+l+'</div></div>'}
var fb=D.feedback;
var med=D.medianS===null?'–':String(D.medianS).replace('.',',')+' s';
document.getElementById('tiles').innerHTML=tile(D.gesamt,'Fragen gesamt')+tile(D.anteilBeantwortbar===null?'–':D.anteilBeantwortbar+' %','Anteil beantwortbar')+tile(med,'Median Antwortzeit')+tile(D.erlassAnzahl,'Erlass-Suche genutzt')+tile(fb.quote===null?'noch keine Daten':fb.quote+' %','Daumen hoch ('+(fb.positiv+fb.negativ)+' Bewertungen)');
if(D.demo)document.getElementById('demo').hidden=false;
function liste(id,arr,f){document.getElementById(id).innerHTML=arr.length?arr.map(f).join(''):'<li>Keine Einträge im Zeitraum.</li>'}
liste('lk',D.luecken,function(e){return '<li><span>'+esc(e.stichwort)+'</span><span class=n>'+e.anzahl+'×</span></li>'});
var NAMEN={personenbezug:'Personenbezug erkannt',benotung:'Benotungsanfrage abgelehnt',manipulation:'Manipulationsversuch abgewehrt',themenfremd:'Themenfremde Frage',unklar:'Unklare Frage'};
liste('sk',D.sicherheit,function(e){return '<li><span>'+esc(NAMEN[e.kategorie]||e.kategorie)+'</span><span class=n>'+e.anzahl+'</span></li>'});
document.getElementById('st').textContent='Stand: '+D.stand+' (Europe/Berlin)';
var charts=[];
function cv(n){return getComputedStyle(document.documentElement).getPropertyValue(n).trim()}
function bar(id,labels,data,horiz){var c=new Chart(document.getElementById(id),{type:'bar',data:{labels:labels,datasets:[{data:data,backgroundColor:cv('--acc'),borderRadius:4}]},options:{indexAxis:horiz?'y':'x',responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{color:cv('--mut'),precision:0},grid:{color:cv('--line')}},y:{beginAtZero:true,ticks:{color:cv('--mut'),precision:0},grid:{color:cv('--line')}}}}});charts.push(c)}
function draw(){
 if(!window.Chart)return;
 charts.forEach(function(c){c.destroy()});charts=[];
 bar('c1',D.themen.map(function(t){return t.name}),D.themen.map(function(t){return t.anzahl}),true);
 bar('c2',['Mo','Di','Mi','Do','Fr','Sa','So'],D.wochentage,false);
 bar('c3',D.stunden.map(function(_,i){return String(i)}),D.stunden,false);
}
function dark(){var t=document.documentElement.getAttribute('data-theme');return t?t==='dark':matchMedia('(prefers-color-scheme: dark)').matches}
try{var s=localStorage.getItem('kk-theme');if(s)document.documentElement.setAttribute('data-theme',s)}catch(e){}
document.getElementById('tg').onclick=function(){var n=dark()?'light':'dark';document.documentElement.setAttribute('data-theme',n);try{localStorage.setItem('kk-theme',n)}catch(e){}draw()};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',draw);
draw();
</script></body></html>`;
return [{ json: { html } }];
